<template>
	<view class="square-page" :class="{ 'review-mode': reviewMode }">
		<view class="square-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="header-aura aura-left"></view>
			<view class="header-aura aura-right"></view>
			<view class="top-row">
				<view class="brand-block">
					<view class="brand-slogan">
						<text class="brand-subtitle">{{ slogo }}</text>
						<view class="slogan-mark"></view>
						<view class="slogan-spark"></view>
					</view>
				</view>
			</view>

			<view class="nav-row">
				<view class="feed-tabs">
					<view
						v-for="item in navTabs"
						:key="item.value"
						class="feed-tab"
						:class="{ active: activeNavTab === item.value }"
						@click="activeNavTab = item.value"
					>
						<text>{{ item.label }}</text>
					</view>
				</view>
				<!-- <view class="filter-button" @click="openFilterPanel">
					<text>筛选</text>
					<text class="filter-icon"></text>
				</view> -->
			</view>
		</view>

		<scroll-view
			class="content-scroll"
			:style="{ top: headerTotalHeight + 'px' }"
			scroll-y
			enhanced
			:show-scrollbar="false"
			refresher-enabled
			refresher-background="#fffafd"
			refresher-default-style="none"
			:refresher-threshold="36"
			:refresher-max-drag-distance="44"
			:refresher-triggered="refresherTriggered"
			@refresherrefresh="handleRefresherRefresh"
			@scrolltolower="loadMoreFeed"
		>
			<view slot="refresher" class="refresh-slot">
				<text class="refresh-icon">↻</text>
				<text>{{ refreshing ? '正在刷新广场' : '下拉刷新广场' }}</text>
				<view class="soft-dots">
					<text></text>
					<text></text>
					<text></text>
				</view>
			</view>

			<view class="content-body">
				<view v-if="loading && !visiblePosts.length" class="skeleton-list">
					<view v-for="index in 3" :key="index" class="skeleton-card">
						<view class="skeleton-head">
							<view class="skeleton-avatar skeleton-shimmer"></view>
							<view class="skeleton-lines">
								<view class="skeleton-line short skeleton-shimmer"></view>
								<view class="skeleton-line tiny skeleton-shimmer"></view>
							</view>
						</view>
						<view class="skeleton-line full skeleton-shimmer"></view>
						<view class="skeleton-grid">
							<view class="skeleton-img skeleton-shimmer"></view>
							<view class="skeleton-img skeleton-shimmer"></view>
							<view class="skeleton-img skeleton-shimmer"></view>
						</view>
					</view>
				</view>

				<view v-else-if="!visiblePosts.length" class="empty-state">
					<image src="/static/empty.png" mode="aspectFit" />
					<text>这里还没有内容</text>
				</view>

				<view v-else class="post-list">
					<view
						v-for="post in visiblePosts"
						:key="post.id"
						class="post-card"
						@click="goDetail(post.id)"
					>
						<view class="post-head">
							<image class="avatar" :src="post.avatar" mode="aspectFill" @click.stop="goUser(post.userId || post.id)" />
							<view class="user-meta">
								<view class="name-row">
									<VipName class="nickname" :name="post.name" :is-member="!reviewMode && post.isMember" />
									<view v-if="!reviewMode && post.profileCompleted && post.gender && post.age > 0 && post.age <= 120" class="user-pill" :class="post.gender === '男' ? 'male' : 'female'">
										<image class="gender-icon" :src="getGenderIcon(post.gender)" mode="aspectFit" />
										<text>{{ post.age }}</text>
									</view>
								</view>
								<text class="time-line">
									<text>{{ post.time }}</text>
									<text v-if="!reviewMode && post.city"> · {{ post.city }}</text>
								</text>
							</view>
							<!-- <view v-if="post.followable" class="follow-button" @click.stop="toggleFollow(post)">
								<text>{{ post.followed ? '已关注' : '关注' }}</text>
							</view> -->
							<text class="more-dot">•••</text>
						</view>

						<view class="post-content-preview">
							<text class="post-text">{{ getPostPreview(post.text) }}<text v-if="isLongPost(post.text)" class="read-more" @click.stop="goDetail(post.id)"><text class="read-more-ellipsis">... </text>查看全文</text></text>
						</view>

						<view v-if="post.images.length" class="image-grid">
							<image
								v-for="(url, index) in post.images.slice(0, 3)"
								:key="index"
								class="post-image"
								:src="url"
								mode="aspectFill"
							/>
						</view>

						<view class="place-chip">
							<text class="pin-icon"></text>
							<text>{{ post.place }}</text>
						</view>

						<view class="post-footer">
							<view class="action like-action" :class="{ active: post.resonated, busy: post.resonanceBusy }" @click.stop="toggleLike(post)">
								<image class="like-icon" :src="post.resonated ? '/static/img/dianzan-active.png' : '/static/img/dianzan.png'" mode="aspectFit" />
								<text>{{ post.likes }}</text>
							</view>
							<view class="action">
								<image class="comment-icon" src="/static/tab/message.png" mode="aspectFit" />
								<text>{{ post.comments }}</text>
							</view>
							<view class="action" :class="{ 'favorite-active': post.favorited }" @click.stop="toggleFavorite(post)">
								<text class="star-icon">{{ post.favorited ? '★' : '☆' }}</text>
								<text>{{ post.favorites }}</text>
							</view>
							<view class="action share-action">
								<image class="share-icon" src="/static/img/share-icon.png" mode="aspectFit" />
								<text>分享</text>
							</view>
						</view>
					</view>
				</view>

				<view v-if="visiblePosts.length" class="load-more-state">
					<text class="load-text">
						{{ loadingMore ? '正在加载更多回响' : (hasMore ? '继续下滑，发现更多隐秘回响' : '暂时只有这些啦') }}
					</text>
					<view v-if="loadingMore || hasMore" class="soft-dots">
						<text></text>
						<text></text>
						<text></text>
					</view>
				</view>
			</view>
		</scroll-view>

		<view v-if="filterPanelVisible" class="filter-mask" @click="closeFilterPanel">
			<view class="filter-sheet" @click.stop>
				<view class="sheet-head">
					<view class="sheet-title-block">
						<text class="sheet-title">选择标签</text>
					</view>
					<text class="sheet-close" @click="closeFilterPanel">×</text>
				</view>
				<view class="filter-grid">
					<view
						v-for="item in categories"
						:key="item.value"
						class="filter-chip"
						:class="{ active: activeCategory === item.value }"
						@click="selectCategory(item.value)"
					>
						<text>{{ item.label }}</text>
					</view>
				</view>
			</view>
		</view>

		<view class="publish-fab" hover-class="publish-fab-hover" hover-stay-time="80" @click="goPublish">
			<text class="publish-fab-plus">＋</text>
			<text class="publish-fab-text">发布</text>
		</view>
		<ReviewTabBar v-if="reviewMode" active="square" />
	</view>
</template>

<script>
import { completeBrowseTask } from '../../api/diamond';
import { fetchSquareFeed, toggleThoughtFavorite, toggleThoughtResonance } from '../../api/thought';
import { followUser, unfollowUser } from '../../api/follow';
import { COMMUNITY_SLOGO, COMMUNITY_TAG_OPTIONS, DEFAULT_AVATAR_URL, SLOGO, TAG_OPTIONS } from '../../config';
import {
	isFullMode,
	isResolvedCommunityMode,
	loadAppMode,
	syncTabBarVisibility
} from '../../utils/appMode';
import { showRequestError } from '../../utils/feedback';
import * as profileGuard from '../../utils/profileGuard';
import { consumeSquareFeedRefresh } from '../../utils/squareFeedRefresh';
import {
	getReviewFeedPage,
	toggleReviewFeedFavorite,
	toggleReviewFeedResonance
} from '../../mock/reviewFeed';
import VipName from '../../components/VipName.vue';
import ReviewTabBar from '../../components/ReviewTabBar.vue';

const IMAGE_BASE = '/static/square/';

export default {
	components: { ReviewTabBar, VipName },
	data() {
		const reviewMode = isResolvedCommunityMode();
		return {
			reviewMode,
			statusBarHeight: 44,
			headerTotalHeight: 128,
			loading: false,
			refreshAfterCurrentLoad: false,
			refreshing: false,
			refresherTriggered: false,
			loadingMore: false,
			page: 1,
			pageSize: 10,
			hasMore: true,
			slogo: reviewMode ? COMMUNITY_SLOGO : SLOGO,
			activeNavTab: 'recommend',
			activeCategory: 'all',
			filterPanelVisible: false,
			navTabs: reviewMode
				? [{ label: '最新', value: 'recommend' }]
				: [
					{ label: '推荐', value: 'recommend' },
					{ label: '关注', value: 'follow' },
					{ label: '附近', value: 'nearby' }
				],
			categories: [
				{ label: '全部', value: 'all' },
				...(reviewMode ? COMMUNITY_TAG_OPTIONS : TAG_OPTIONS).map((tag) => ({ label: tag, value: tag }))
			],
			posts: [],
			fallbackPosts: [
				{
					id: 'life_001',
					name: '心语来客',
					avatar: DEFAULT_AVATAR_URL,
					gender: '女',
					age: 22,
					time: '5分钟前',
					city: '杭州',
					text: '有一个念头我永远不会真的说出口。\n但它确实存在过，像一封没有寄出的信。',
					place: '未寄出的信',
					images: [`${IMAGE_BASE}sunset-lake.jpg`, `${IMAGE_BASE}evening-pier.jpg`, `${IMAGE_BASE}coffee-sunset.jpg`],
					likes: 128,
					comments: 32,
					favorites: 56,
					favorited: false,
					category: '禁忌',
					followable: false,
					followed: false
				},
				{
					id: 'life_002',
					name: '平行剧本',
					avatar: DEFAULT_AVATAR_URL,
					gender: '男',
					age: 24,
					time: '30分钟前',
					city: '幻想境地',
					text: '如果人生可以重开一次，我想成为一个完全相反的人。\n不是更好，只是更真实。',
					place: '平行人生脚本',
					images: [`${IMAGE_BASE}mountain-sign.jpg`, `${IMAGE_BASE}green-hills.jpg`, `${IMAGE_BASE}trail-view.jpg`],
					likes: 96,
					comments: 18,
					favorites: 42,
					favorited: false,
					category: '平行世界',
					followable: false,
					followed: false
				},
				{
					id: 'life_003',
					name: '深夜封存',
					avatar: DEFAULT_AVATAR_URL,
					gender: '女',
					age: 25,
					time: '1小时前',
					city: '只对自己可见',
					text: '我为一个不应该靠近的人心动过。\n这件事没有结果，也不需要被现实批准。',
					place: '暗恋档案',
					images: [`${IMAGE_BASE}coffee-sunset.jpg`, `${IMAGE_BASE}sunset-lake.jpg`, `${IMAGE_BASE}evening-pier.jpg`],
					likes: 72,
					comments: 14,
					favorites: 33,
					favorited: false,
					category: '暗恋',
					followable: false,
					followed: false
				},
				{
					id: 'life_004',
					name: '失控边缘',
					avatar: DEFAULT_AVATAR_URL,
					gender: '女',
					age: 30,
					time: '2小时前',
					city: '精神碎片',
					text: '有些冲动我不会执行，只会把它写下来。\n被看见之后，它反而安静了一点。',
					place: '封存区',
					images: [`${IMAGE_BASE}green-hills.jpg`, `${IMAGE_BASE}trail-view.jpg`, `${IMAGE_BASE}mountain-sign.jpg`],
					likes: 84,
					comments: 21,
					favorites: 39,
					favorited: false,
					category: '失控',
					followable: false,
					followed: false
				}
			]
		};
	},
	computed: {
		filteredPosts() {
			let list = this.posts;
			if (this.activeNavTab === 'follow') {
				list = list.filter((item) => item.followed);
			}
			if (this.activeCategory !== 'all') {
				list = list.filter((item) => item.category === this.activeCategory);
			}
			return list;
		},
		visiblePosts() {
			return this.filteredPosts;
		}
	},
	watch: {
		activeNavTab() {
			this.loadFeed(true);
		}
	},
	async onLoad() {
		await loadAppMode();
		this.syncModePresentation();
		this.setHeaderMetrics();
		this.loadFeed(true);
	},
	async onShow() {
		await loadAppMode();
		this.syncModePresentation();
		if (isFullMode()) completeBrowseTask().catch(() => {});
		if (consumeSquareFeedRefresh()) {
			if (this.loading) this.refreshAfterCurrentLoad = true;
			else this.loadFeed(true, { silent: true });
		}
	},
	methods: {
		syncModePresentation() {
			this.reviewMode = isResolvedCommunityMode();
			this.slogo = this.reviewMode ? COMMUNITY_SLOGO : SLOGO;
			this.navTabs = this.reviewMode
				? [{ label: '最新', value: 'recommend' }]
				: [
					{ label: '推荐', value: 'recommend' },
					{ label: '关注', value: 'follow' },
					{ label: '附近', value: 'nearby' }
				];
			this.categories = [
				{ label: '全部', value: 'all' },
				...(this.reviewMode ? COMMUNITY_TAG_OPTIONS : TAG_OPTIONS).map((tag) => ({ label: tag, value: tag }))
			];
			if (this.reviewMode) this.activeNavTab = 'recommend';
			syncTabBarVisibility();
		},
		setHeaderMetrics() {
			try {
				const info = uni.getSystemInfoSync();
				const rpxToPx = (info.windowWidth || 375) / 750;
				this.statusBarHeight = info.statusBarHeight || 44;
				this.headerTotalHeight = this.statusBarHeight + Math.round(144 * rpxToPx);
			} catch (error) {
				this.statusBarHeight = 44;
				this.headerTotalHeight = 116;
			}
		},
		resetList() {
			this.page = 1;
			this.hasMore = true;
		},
		getFeedParams(page = this.page) {
			return {
				page,
				pageSize: this.pageSize
			};
		},
		normalizeFeedResult(result) {
			if (Array.isArray(result)) {
				return {
					items: result,
					hasMore: false,
					page: 1
				};
			}
			return {
				items: Array.isArray(result && result.items) ? result.items : [],
				hasMore: Boolean(result && result.hasMore),
				page: Number((result && result.page) || this.page)
			};
		},
		async loadFeed(reset = false, options = {}) {
			if (reset) {
				this.page = 1;
				this.hasMore = true;
			}
			if (reset && !options.silent) this.loading = true;
			if (!reset) this.loadingMore = true;

			try {
				const targetPage = reset ? 1 : this.page;
				const feedParams = this.getFeedParams(targetPage);
				const feed = this.reviewMode
					? getReviewFeedPage(feedParams)
					: await fetchSquareFeed(feedParams);
				const result = this.normalizeFeedResult(feed);
				const mappedItems = result.items.map((item) => this.mapFeedItem(item));
				this.posts = reset ? mappedItems : [...this.posts, ...mappedItems];
				this.page = result.page || targetPage;
				this.hasMore = result.hasMore;
			} catch (error) {
				if (!this.posts.length && !this.reviewMode) {
					this.posts = this.fallbackPosts;
					this.hasMore = false;
				}
				if (!options.silent) showRequestError(error, '广场加载失败');
			} finally {
				this.loading = false;
				this.loadingMore = false;
				if (this.refreshAfterCurrentLoad) {
					this.refreshAfterCurrentLoad = false;
					this.$nextTick(() => this.loadFeed(true, { silent: true }));
				}
			}
		},
		handleRefresherRefresh() {
			if (this.refreshing) return;
			this.refreshing = true;
			this.refresherTriggered = true;
			this.loadFeed(true, { silent: true }).finally(() => {
				this.refreshing = false;
				this.refresherTriggered = false;
			});
		},
		loadMoreFeed() {
			if (this.loadingMore || !this.hasMore) return;
			this.page += 1;
			this.loadFeed(false);
		},
		async goDetail(id) {
			if (!this.reviewMode && !(await profileGuard.ensureProfileCompleted({ actionText: '查看详情' }))) return;
			uni.navigateTo({ url: `/pages/detail/index?id=${id}` });
		},
		async goUser(id) {
			if (this.reviewMode) return;
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '查看主页' }))) return;
			uni.navigateTo({ url: `/pages/user/index?id=${id}` });
		},
		async goPublish() {
			if (!this.reviewMode && !(await profileGuard.ensureProfileCompleted({ actionText: '发布' }))) return;
			uni.navigateTo({ url: '/pages/create/index' });
		},
		getGenderIcon(gender) {
			return gender === '男' ? '/static/img/nan-icon.png' : '/static/img/nv-icon.png';
		},
		getImageUrls(images = []) {
			return (Array.isArray(images) ? images : [])
				.map((item) => (typeof item === 'string' ? item : item && item.url))
				.filter(Boolean);
		},
		isLongPost(content) {
			const lines = String(content || '').replace(/\r\n?/g, '\n').split('\n');
			const visualLineCount = lines.reduce((total, line) => {
				const visualLength = Array.from(line).reduce((length, character) => (
					length + (/^[\x00-\xff]$/.test(character) ? 0.55 : 1)
				), 0);
				return total + Math.max(1, Math.ceil(visualLength / 24));
			}, 0);
			return visualLineCount > 4;
		},
		getPostPreview(content) {
			const normalizedContent = String(content || '').replace(/\r\n?/g, '\n');
			if (!this.isLongPost(normalizedContent)) return normalizedContent;

			const lineWidth = 24;
			const previewWidth = lineWidth * 3.5;
			let usedWidth = 0;
			let currentLineWidth = 0;
			let preview = '';

			for (const character of Array.from(normalizedContent)) {
				if (character === '\n') {
					usedWidth += lineWidth - currentLineWidth;
					if (usedWidth >= previewWidth) break;
					preview += character;
					currentLineWidth = 0;
					continue;
				}

				const characterWidth = /^[\x00-\xff]$/.test(character) ? 0.55 : 1;
				if (currentLineWidth + characterWidth > lineWidth) {
					usedWidth += lineWidth - currentLineWidth;
					currentLineWidth = 0;
				}
				if (usedWidth + characterWidth > previewWidth) break;
				preview += character;
				usedWidth += characterWidth;
				currentLineWidth += characterWidth;
			}

			return preview.trimEnd();
		},
		formatFeedTime(value) {
			if (!value) return '';
			const date = new Date(value);
			if (Number.isNaN(date.getTime())) return '';
			const diff = Date.now() - date.getTime();
			const minute = 60 * 1000;
			const hour = 60 * minute;
			const day = 24 * hour;
			if (diff < minute) return '刚刚';
			if (diff < hour) return `${Math.floor(diff / minute)}分钟前`;
			if (diff < day) return `${Math.floor(diff / hour)}小时前`;
			if (diff < 7 * day) return `${Math.floor(diff / day)}天前`;
			return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`;
		},
		mapGender(value) {
			if (value === '男' || value === 'male' || value === 1 || value === '1') return '男';
			if (value === '女' || value === 'female' || value === 2 || value === '2') return '女';
			return '';
		},
		mapFeedItem(item = {}) {
			const tags = Array.isArray(item.tags) ? item.tags : [];
			const rawCategory = tags[0] || item.topicTitle || '秘密';
			const category = this.reviewMode
				? (COMMUNITY_TAG_OPTIONS.includes(rawCategory) ? rawCategory : '日常')
				: rawCategory;
			const gender = this.mapGender(item.authorGender || item.gender || item.sex);
			const age = Number(item.authorAge || item.age || 0) || 0;
			const city = String(item.authorCity || item.city || item.location || '').trim();
			const hasProfileCompletedFlag = Object.prototype.hasOwnProperty.call(item, 'authorProfileCompleted');
			const profileCompleted = hasProfileCompletedFlag
				? item.authorProfileCompleted === true || Number(item.authorProfileCompleted || 0) === 1
				: Boolean(item.authorNickname && item.authorAvatarUrl && gender && age > 0 && city);
			return {
				id: item.id,
				userId: item.userId || item.authorId || item.id,
				name: item.authorNickname || item.displayName || item.authorName || item.authorStampNo || '想法来客',
				isMember: Boolean(item.authorIsMember),
				avatar: item.authorAvatarUrl || DEFAULT_AVATAR_URL,
				gender,
				age,
				profileCompleted,
				time: this.formatFeedTime(item.createdAt),
				city,
				text: item.content || item.summary || '',
				place: this.reviewMode ? category : (item.topicTitle || category),
				images: this.getImageUrls(item.images),
				likes: item.resonanceCount || item.likes || 0,
				resonated: Boolean(item.isResonated || item.resonated),
				resonanceBusy: false,
				comments: item.commentCount || (Array.isArray(item.comments) ? item.comments.length : 0),
				favorites: item.favoriteCount || item.favorites || 0,
				favorited: Boolean(item.isFavorited || item.favorited),
				category,
				followable: Boolean(item.followable),
				followed: Boolean(item.followed)
			};
		},
		isLocalPost(post = {}) {
			const id = String(post.id || '');
			return id.startsWith('life_') || id.startsWith('review_');
		},
		async toggleLike(post) {
			if (!post || !post.id || post.resonanceBusy) return;
			if (!this.reviewMode && !(await profileGuard.ensureProfileCompleted({ actionText: '点赞' }))) return;
			const previousResonated = Boolean(post.resonated);
			const previousLikes = Number(post.likes || 0);
			const nextResonated = !previousResonated;
			post.resonated = nextResonated;
			post.likes = Math.max(0, previousLikes + (nextResonated ? 1 : -1));

			if (this.isLocalPost(post)) {
				if (this.reviewMode) toggleReviewFeedResonance(post.id);
				uni.showToast({ title: nextResonated ? '已点赞' : '已取消点赞', icon: 'none' });
				return;
			}

			post.resonanceBusy = true;
			try {
				const response = await toggleThoughtResonance(post.id);
				if (response && typeof response === 'object') {
					const nextLikes = response.resonanceCount !== undefined ? response.resonanceCount : response.likes;
					post.resonated = Boolean(response.isResonated || response.resonated);
					post.likes = nextLikes !== undefined ? Number(nextLikes) : post.likes;
				}
				uni.showToast({ title: post.resonated ? '已点赞' : '已取消点赞', icon: 'none' });
			} catch (error) {
				post.resonated = previousResonated;
				post.likes = previousLikes;
				showRequestError(error, nextResonated ? '点赞失败' : '取消点赞失败');
			} finally {
				post.resonanceBusy = false;
			}
		},
		async toggleFavorite(post) {
			if (!post || !post.id) return;
			if (!this.reviewMode && !(await profileGuard.ensureProfileCompleted({ actionText: '收藏' }))) return;
			const previousFavorited = Boolean(post.favorited);
			const previousFavorites = Number(post.favorites || 0);
			const nextFavorited = !previousFavorited;
			post.favorited = nextFavorited;
			post.favorites = Math.max(0, previousFavorites + (nextFavorited ? 1 : -1));

			if (this.isLocalPost(post)) {
				if (this.reviewMode) toggleReviewFeedFavorite(post.id);
				uni.showToast({ title: nextFavorited ? '已收藏' : '已取消收藏', icon: 'none' });
				return;
			}

			try {
				const response = await toggleThoughtFavorite(post.id);
				if (response && typeof response === 'object') {
					const nextFavorites = response.favoriteCount !== undefined ? response.favoriteCount : response.favorites;
					post.favorited = Boolean(response.isFavorited || response.favorited);
					post.favorites = nextFavorites !== undefined ? nextFavorites : post.favorites;
				}
				uni.showToast({ title: post.favorited ? '已收藏' : '已取消收藏', icon: 'none' });
			} catch (error) {
				post.favorited = previousFavorited;
				post.favorites = previousFavorites;
				showRequestError(error, nextFavorited ? '收藏失败' : '取消收藏失败');
			}
		},
		async toggleFollow(post) {
			if (!post || !post.followable) return;
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '关注' }))) return;
			const targetUserId = post.userId;
			const nextFollowed = !post.followed;
			const previousPosts = this.posts.map((item) => ({ id: item.id, followed: item.followed }));
			this.posts = this.posts.map((item) => {
				if (item.userId !== targetUserId) return item;
				return { ...item, followed: nextFollowed };
			});
			try {
				if (nextFollowed) {
					await followUser(targetUserId);
					uni.showToast({ title: '已关注', icon: 'none' });
				} else {
					await unfollowUser(targetUserId);
					uni.showToast({ title: '已取关', icon: 'none' });
				}
			} catch (error) {
				const stateMap = new Map(previousPosts.map((item) => [item.id, item.followed]));
				this.posts = this.posts.map((item) => ({
					...item,
					followed: stateMap.has(item.id) ? stateMap.get(item.id) : item.followed
				}));
				showRequestError(error, nextFollowed ? '关注失败' : '取关失败');
			}
		},
		openFilterPanel() {
			this.filterPanelVisible = true;
		},
		closeFilterPanel() {
			this.filterPanelVisible = false;
		},
		selectCategory(value) {
			this.activeCategory = value;
			this.closeFilterPanel();
			this.resetList();
		}
	}
};
